import org.prairielearn.api.PlatformApiPrecheck;import queuecheck.CharAccess;import java.util.*;
public class ApiContract {public static void check(PlatformApiPrecheck.Api api)throws Exception {var matched=new ArrayList<String>();for(String name:api.typeNames("FixedQueue")){try{new CharAccess(api.type(name));matched.add(name);}catch(ReflectiveOperationException ignored){}}api.expect(!matched.isEmpty(),"FixedQueue(int), put/get, ICharQ, checked отказы","совместимое опубликованное API отсутствует");if(matched.size()>1)throw new IllegalStateException("Не разрешена адресация нескольких законных FixedQueue: "+matched+"; оценки нет");}}
